pub fn quiz_form(
    quiz: Option<&Quiz>,
    title: &str,
    winners: &str,
    messages: &[&str],
    token: &str,
) -> String {
    let heading = if quiz.is_some() {
        "Quiz settings"
    } else {
        "New quiz"
    };
    let url = quiz
        .map(|q| format!("/moderate/quizzes/{}", q.id))
        .unwrap_or("/moderate/quizzes".into());
    let back = quiz
        .map(|q| format!("/moderate/quizzes/{}", q.id))
        .unwrap_or("/moderate".into());
    let mut body = format!(
        r#"<main class="admin-main">{}<div class="page-head"><h1>{heading}</h1></div><div class="card"><form method="post" action="{url}">{}{}<div class="field"><label for="title">Title</label><input class="input" id="title" name="title" value="{}" required autofocus></div><div class="field"><label for="number-of-winners">Number of winners</label><input class="input" id="number-of-winners" name="number_of_winners" type="number" min="1" step="1" value="{}" required></div><div class="buttons"><button class="btn btn--pink" type="submit">Save quiz</button><a class="btn btn--ghost" href="{back}">Cancel</a></div></form></div>"#,
        crumb(
            &back,
            quiz.map(|q| q.title.as_str()).unwrap_or("All quizzes")
        ),
        csrf(token),
        errors(messages),
        escape(title),
        escape(winners)
    );
    if quiz.is_some() {
        write!(body, r#"<form method="post" action="{url}/delete" data-confirm="Delete this quiz and all its questions?">{}<button class="btn btn--danger" type="submit">Delete quiz</button></form>"#, csrf(token)).unwrap();
    }
    body.push_str("</main>");
    page(heading, &body, token)
}

pub fn quiz_page(quiz: &Quiz, questions: &[Question], token: &str) -> String {
    let url = format!("/moderate/quizzes/{}", quiz.id);
    let active = questions.iter().filter(|q| q.active).count();
    let mut body = format!(
        r#"<main class="admin-main">{}<div class="page-head"><div><h1>{}</h1><div class="meta mt-2"><span id="active-count">{active}</span> of {} questions active · <a href="{url}/settings">Settings</a></div></div><div class="buttons"><form method="post" action="{url}/games"><input type="hidden" name="csrf" value="{token}"><button class="btn btn--pink">Start a game</button></form><a class="btn btn--ghost" href="{url}/export">Export</a><a class="btn btn--ghost" href="{url}/preview">Preview</a></div></div><section class="section mt-0"><div class="section-head"><h2>Questions</h2><a class="btn" href="{url}/questions/new">Add question</a></div><div id="save-status" role="status"></div>"#,
        crumb("/moderate", "All quizzes"),
        escape(&quiz.title),
        questions.len()
    );
    if questions.is_empty() {
        body.push_str(r#"<div class="empty"><h3>A blank slate</h3><p>Add your first question to get the conversation started.</p></div>"#);
